const root="/tests/prelims";
const mockLocalDate=(s?:string)=>s?new Date(Date.parse(s)-new Date(s).getTimezoneOffset()*60000).toISOString().slice(0,16):'';
export function useMockAPI(){const {client,user}=useAuth();return useCallback(async<T,>(op:string,p:Record<string,unknown>={}):Promise<T>=>{if(!client)throw Error("The test service is not available. Please try again shortly.");const {data,error}=await client.rpc("mock_lab",{op,p});if(error)throw Error(/permission denied|does not exist|schema cache|violates|invalid input syntax/i.test(error.message)?'The request could not be completed. Check the test details and try again.':error.message);return data as T;},[client,user?.id]);}
function SignIn(){const location=useLocation();return <section className="card mock-gate"><ShieldCheck/><h2>Keep every attempt in your own account</h2><p>Sign in to start a mock, save answers and see your score, report and participant rank.</p><div className="button-group"><Link className="btn primary" to="/login" state={{returnTo:location.pathname}}>Log in</Link><Link className="btn secondary" to="/signup" state={{returnTo:location.pathname}}>Create account</Link></div></section>;}
function Loading(){return <p className="card" role="status">Opening the mock test lab…</p>;}
function ErrorNote({message}:{message:string}){return message?<p className="mock-error" role="alert">{message}</p>:null;}
const nav=[['discover','Discover Tests'],['coaching','Coaching-wise'],['series','Test Series'],['years','Year-wise'],['sectional','Sectional Tests'],['full-length','Full-Length Tests'],['csat','CSAT Tests'],['my-tests','My Tests'],['reports','Test Reports'],['mistakes','Mistake Notebook'],['bookmarks','Bookmarked Questions'],['leaderboards','Leaderboards']];
