 {detail.statistics&&<div className="stats-grid four">{['mean','median','highest','accuracy'].map(key=><DashboardCard key={key} title={`Community ${key}`} value={fmtMock(detail.statistics?.[key],key==='accuracy'?'%':'')}/>)}</div>}
 {!auth.user?<SignIn/>:<div className="mock-start"><ErrorNote message={error}/>{!profile&&<label>Leaderboard display name<input aria-label="Leaderboard display name" maxLength={30} value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. MissionUPSC"/><small>Only this name and performance statistics appear publicly.</small></label>}<label>Attempt mode<select aria-label="Mock attempt mode" value={mode} onChange={e=>setMode(e.target.value)}><option value="official">First eligible attempt / resume</option><option value="practice">Practice only</option></select></label><button className="btn primary" disabled={busy||t.status!=='active'||(!profile&&name.trim().length<2)} onClick={start}>{busy?'Opening…':'Start test'}</button></div>}
