 const cache=(a:MockAttempt)=>{try{localStorage.setItem(storageKey,JSON.stringify({answers:a.answers,index:a.index,sequence:a.sequence}));}catch{setSync("Device backup is unavailable; keep this tab open until cloud save completes.");}};
