type RecallDocument={title:string;items:{number:number;title:string;text:string}[]};
function MockRecallSheet({attempt}:{attempt:MockAttempt}){
 const api=useMockAPI(),[document,setDocument]=useState<RecallDocument|null>(null),[query,setQuery]=useState(''),[busy,setBusy]=useState(true),[error,setError]=useState('');
 const load=useCallback(async()=>{setBusy(true);setError('');try{setDocument(await api<RecallDocument>('report-document',{attemptId:attempt.id,kind:'recall'}));}catch(e){setError((e as Error).message);}finally{setBusy(false);}},[api,attempt.id]);
 useEffect(()=>{void load();},[load]);
 const terms=query.trim().toLowerCase(),questionNumber=/^(?:q(?:uestion)?\s*)?(\d+)$/.exec(terms);
 const items=document?.items.filter(item=>!terms||(questionNumber?item.number===Number(questionNumber[1]):`q${item.number} ${item.title} ${item.text}`.toLowerCase().includes(terms)))||[];
 return <section className="mock-recall-sheet" aria-label="Recall sheet">
  <div className="card mock-recall-toolbar"><h3>{document?.title||'Recall Sheet'}</h3><p>Revisit each question’s key takeaway after completing your exam.</p>
   <ErrorNote message={error}/>{error&&<button className="btn secondary" disabled={busy} onClick={()=>void load()}>Retry recall sheet</button>}
   {busy?<p role="status">Opening your recall sheet…</p>:document&&<><label>Search recall sheet<input type="search" aria-label="Search recall sheet" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search a topic or question number…"/></label><p role="status" aria-live="polite">{items.length} of {document.items.length} recall entries</p></>}
  </div>
  {items.map(item=><article className="card mock-recall-entry" key={item.number}><h4>Q{item.number}. {item.title}</h4><p className="mock-question-text">{item.text}</p></article>)}
  {!busy&&document&&!items.length&&<p className="card">No recall entries match your search.</p>}
 </section>;
}
